// src/refiner/loop.ts
import { Task } from '../models/task';
import { loadAllTasks, saveTasks } from '../storage/json';

export async function refineTask(id: number, feedback: string): Promise<Task> {
  const tasks = await loadAllTasks();
  const taskIndex = tasks.findIndex(t => t.id === id);
  if (taskIndex === -1) throw new Error(`Task ${id} not found`);
  const task = tasks[taskIndex];
  const updated = { ...task, version: (task.version || 0) + 1 };
  // Heuristic: Simple update based on feedback
  if (feedback.includes('fix')) updated.status = 'in-progress';
  updated.history = [...(task.history || []), { timestamp: new Date(), changes: 'Applied feedback', feedback }];
  tasks[taskIndex] = updated;
  await saveTasks(tasks);
  return updated;
}

